      y35 = { title: "\u0938\u0902\u0917\u094D\u0930\u0939 \u092A\u094D\u0930\u0915\u093E\u0936\u093F\u0924 \u0915\u0930\u093E", itemName: "\u0935\u0938\u094D\u0924\u0941 \u091A\u0947 \u0928\u093E\u0935", authorName: "\u0932\u0947\u0916\u0915 \u091A\u0947 \u0928\u093E\u0935", githubUsername: "\u0917\u093F\u091F\u0939\u092C \u0935\u093E\u092A\u0930\u0915\u0930\u094D\u0924\u093E\u0928\u093E\u0935", twitterUsername: "\u091F\u094D\u0935\u093F\u091F\u0930 \u0935\u093E\u092A\u0930\u0915\u0930\u094D\u0924\u093E\u0928\u093E\u0935", libraryName: "\u0938\u0902\u0917\u094D\u0930\u0939\u093E\u091A\u0947 \u0928\u093E\u0935", libraryDesc: "\u0938\u0902\u0917\u094D\u0930\u0939\u093E\u091A\u0947 \u0935\u0930\u094D\u0923\u0928", website: "\u0935\u0947\u092C\u0938\u093E\u0907\u091F", placeholder: { authorName: "\u0924\u0941\u092E\u091A\u0947 \u0928\u093E\u0935 \u0915\u093F\u0935\u094D\u0939\u093E \u0935\u093E\u092A\u0930\u0915\u0930\u094D\u0924\u093E\u0928\u093E\u0935", libraryName: "\u0924\u0941\u092E\u091A\u093E \u0938\u0902\u0917\u094D\u0930\u0939\u093E\u091A\u0947 \u0928\u093E\u0935", libraryDesc: "\u0924\u0941\u092E\u091A\u093E \u0938\u0902\u0917\u094D\u0930\u0939\u093E\u091A\u0947 \u0935\u0930\u094D\u0923\u0928 \u0932\u094B\u0915\u093E\u0902\u0928\u093E \u0938\u0902\u0917\u094D\u0930\u0939\u093E \u092C\u0926\u094D\u0926\u0932 \u091C\u093E\u0923\u0915\u093E\u0930\u0940 \u0926\u0947\u0924\u0940\u0932", githubHandle: "\u0917\u093F\u091F\u0939\u092C \u0939\u0948\u0902\u0921\u0932 (\u0935\u0948\u0915\u0932\u094D\u092A\u093F\u0915), \u090F\u0915\u0926\u093E \u0938\u0902\u0917\u094D\u0930\u0939 \u092A\u0941\u0928\u0930\u093E\u0935\u0932\u094B\u0915\u0928\u093E \u0938\u093E\u0920\u0940 \u091C\u092E\u093E \u0915\u0947\u0932\u094D\u092F\u093E \u0928\u0902\u0924\u0930 \u0939\u0940 \u0924\u0941\u092E\u094D\u0939\u0940\u0902 \u0938\u092E\u094D\u092A\u093E\u0926\u093F\u0924 \u0915\u0930\u0941 \u0936\u0915\u0924\u093E", twitterHandle: "\u091F\u094D\u0935\u093F\u091F\u0930 \u0935\u093E\u092A\u0930\u0915\u093E\u0930\u094D\u092F\u0915 \u0928\u093E\u0935 (\u0935\u0948\u0915\u0932\u094D\u092A\u093F\u0915), \u0924\u094D\u092F\u093E\u092E\u0941\u0933\u0947 \u091F\u094D\u0935\u093F\u091F\u0930 \u0935\u0930 \u091C\u093C\u0939\u0940\u0930\u093E\u0902\u0924\u093F \u0938\u093E\u0920\u0940 \u0915\u094B\u0923\u093E\u0932\u093E \u0917\u0941\u0923 \u0926\u094D\u092F\u093E\u092F\u091A\u0947 \u0939\u0947 \u0906\u092E\u094D\u0939\u093E\u0932\u093E \u0938\u092E\u091C\u0947\u0932", website: "\u0926\u0941\u0935\u093E \u0924\u0941\u092E\u091A\u094D\u092F\u093E \u0935\u0948\u092F\u0915\u094D\u0924\u093F\u0915 \u0935\u0947\u092C-\u0938\u093E\u0907\u091F \u0915\u093F\u0935\u094D\u0939\u093E \u0915\u0941\u0920\u0947 \u0926\u0942\u0938\u0930\u093F\u0915\u0921\u0947 (\u0910\u091A\u094D\u091B\u093F\u0915) \u0915\u0930\u093E\u0935\u093E" }, errors: { required: "\u0906\u0935\u0936\u094D\u092F\u0915 \u0906\u0939\u0947", website: "\u0935\u0948\u0927 \u092F\u0942-\u0906\u0930-\u090F\u0932 \u0926\u094D\u092F\u093E" }, noteDescription: "\u0938\u092E\u093E\u0935\u093F\u0937\u094D\u091F \u0915\u0930\u0923\u094D\u092F\u093E \u0938\u093E\u0920\u0940 \u0924\u0941\u092E\u091A\u093E \u0938\u0902\u0917\u094D\u0930\u0939 \u0939\u094D\u092F\u093E\u091A\u093E\u0924 \u091C\u092E\u093E \u0915\u0930\u093E <link>\u0938\u093E\u0930\u094D\u0935\u091C\u0928\u093F\u0915 \u0938\u0902\u0917\u094D\u0930\u0939\u093E\u091A\u0947 \u0915\u094B\u0920\u093E\u0930</link>\u0907\u0924\u0930 \u0932\u094B\u0915\u093E\u0902\u0928\u093E \u0924\u094D\u092F\u093E\u0902\u091A\u094D\u092F\u093E \u0930\u0947\u0916\u093E\u091A\u093F\u0924\u094D\u0930\u093E\u0902\u092E\u0927\u0947 \u0935\u093E\u092A\u0930\u0923\u094D\u092F\u093E\u0938\u093E\u0920\u0940.", noteGuidelines: "\u0938\u0902\u0917\u094D\u0930\u0939\u093E\u0932\u093E \u0906\u0927\u0940 \u0938\u094D\u0935\u0939\u0938\u094D\u0924\u0947 \u0938\u094D\u0935\u0940\u0915\u0943\u0924\u0940 \u092E\u093F\u0933\u0923\u0947 \u0906\u0935\u0936\u094D\u092F\u0915 \u0906\u0939\u0947. \u0915\u0943\u092A\u092F\u093E \u0939\u0947 \u0935\u093E\u091A\u093E <link>\u092E\u093E\u0930\u094D\u0917\u0926\u0930\u094D\u0936\u0915 \u0924\u0924\u094D\u0924\u094D\u0935\u0947</link> \u091C\u092E\u093E \u0915\u0930\u0923\u094D\u092F\u093E \u092A\u0942\u0930\u094D\u0935\u0940, \u0924\u0941\u092E\u091A\u094D\u092F\u093E \u091C\u0935\u0933 \u090F\u0915 \u0917\u093F\u091F\u0939\u092C \u0916\u093E\u0924\u0947 \u0905\u0938\u0923\u0947 \u0906\u0935\u0936\u094D\u092F\u0915 \u0906\u0939\u0947 \u091C\u0947 \u0938\u0902\u0935\u093E\u0926\u093E \u0938\u093E\u0920\u0940 \u0906\u0923\u093F\u0915 \u092C\u0926\u0932 \u0915\u0930\u0923\u094D\u092F\u093E \u0938\u093E\u0920\u0940 \u0932\u093E\u0917\u0947\u0932, \u0924\u0930\u0940 \u0939\u0947 \u0938\u0930\u094D\u0935 \u0905\u0917\u0926\u0940 \u0906\u0935\u0936\u094D\u092F\u0915 \u0928\u093E\u0939\u0940 \u0906\u0939\u0947.", noteLicense: "\u091C\u092E\u093E \u0915\u0930\u0924\u093E\u0928\u093E \u0924\u0941\u092E\u094D\u0939\u0940\u0902 \u0938\u0939\u092E\u0924\u093F \u0926\u093E\u0916\u0935\u0924\u093E\u0924 \u0906\u0939\u0947 \u0915\u0940 \u0938\u0902\u0917\u094D\u0930\u0939 \u0939\u094D\u092F\u093E\u091A\u093E \u0916\u093E\u0932\u0940 \u092A\u094D\u0930\u0915\u093E\u0936\u093F\u0924 \u0939\u094B\u0908\u0932 <link>\u090F\u092E-\u0906\u0907-\u091F\u0940 \u092A\u0930\u0935\u093E\u0928\u093E, </link>\u091C\u094D\u092F\u093E\u091A\u093E \u0925\u094B\u0921\u0915\u094D\u092F\u093E\u0924 \u0905\u0930\u094D\u0925 \u0915\u094B\u0923\u0940\u0939\u0940 \u0928\u093F\u0930\u094D\u092C\u0902\u0927\u093E\u0902\u0936\u093F\u0935\u093E\u092F \u0935\u093E\u092A\u0930\u0942 \u0936\u0915\u0924\u094B.", noteItems: "\u092A\u094D\u0930\u0924\u0948\u0915 \u0938\u0902\u0917\u094D\u0930\u0939\u093E\u091A\u0947 \u0928\u093E\u0935, \u0928\u0940\u091F \u0936\u094B\u0927\u0928\u093E\u0938\u093E\u0920\u0940, \u0905\u0938\u0923\u0947 \u0906\u0935\u0936\u094D\u092F\u0915 \u0906\u0939\u0947. \u0916\u093E\u0932\u0940 \u0926\u093F\u0932\u0947\u0932\u094D\u092F\u093E \u0935\u0938\u094D\u0924\u0941 \u0938\u092E\u093E\u0935\u093F\u0937\u094D\u091F \u0915\u0947\u0932\u094D\u092F\u093E \u091C\u093E\u0924\u0940\u0932:", atleastOneLibItem: "\u0938\u0941\u0930\u0941 \u0915\u0930\u0923\u094D\u092F\u093E\u0938\u093E\u0920\u0940, \u0915\u0943\u092A\u092F\u093E \u0915\u0930\u0942\u0928, \u0915\u092E\u093F\u0924 \u0915\u092E\u0940 \u090F\u0915 \u0935\u0938\u094D\u0924\u0941 \u0924\u0930\u0940 \u0928\u093F\u0935\u0921\u093E", republishWarning: "\u091F\u0940\u092A: \u0915\u093E\u0939\u0940 \u0928\u093F\u0935\u0921\u0915 \u0906\u092F\u091F\u092E \u0906\u0927\u0940\u091A \u092A\u094D\u0930\u0915\u093E\u0936\u093F\u0924/\u092A\u094D\u0930\u0938\u094D\u0924\u0941\u0924 \u0915\u0947\u0932\u0947\u0932\u0947 \u0906\u0939\u0947\u0924. \u0935\u093F\u0926\u094D\u092F\u092E\u093E\u0928 \u0932\u093E\u092F\u092C\u094D\u0930\u0930\u0940 \u0915\u093F\u0902\u0935\u093E \u092A\u094D\u0930\u0938\u094D\u0924\u0941\u0924\u093F\u0924 \u0906\u092F\u091F\u092E \u0905\u0926\u094D\u092F\u093E\u0935\u093F\u0924 \u0915\u0930\u0924\u093E\u0928\u093E \u0924\u0941\u092E\u094D\u0939\u0940 \u092B\u0915\u094D\u0924 \u0924\u094B \u092A\u0941\u0928\u094D\u0939\u093E \u092A\u094D\u0930\u0938\u094D\u0924\u0941\u0924 \u0915\u0930\u093E." };
      S36 = { title: "\u0938\u0902\u0917\u094D\u0930\u0939 \u091C\u092E\u093E \u0915\u0947\u0932\u093E", content: "\u0927\u0928\u094D\u092F\u0935\u093E\u0926 {{authorName}}. \u0906\u092A\u0932\u093E \u0938\u0902\u0917\u094D\u0930\u0939 \u092A\u0941\u0928\u0930\u093E\u0935\u0932\u094B\u0915\u0928\u093E \u0938\u093E\u0920\u0940 \u091C\u092E\u093E \u091D\u093E\u0932\u093E \u0906\u0939\u0947. \u0924\u0941\u092E\u094D\u0939\u0940\u0902 \u0938\u094D\u0925\u093F\u0924\u093F \u0938\u093E\u0930\u0916\u0940 \u0924\u092A\u093E\u0938\u0942 \u0938\u0915\u0924\u093E<link>\u0907\u0915\u0921\u0947</link>" };
